enum Art { Zahl, Plus, Minus, Mal,
           Durch, KlAuf, KlZu, Ende }

record Token(Art Art, int Wert = 0);

static List<Token> Zerlege(string text)
{
    var tokens = new List<Token>();
    int i = 0;
    while (i < text.Length)
    {
        char c = text[i];
        if (char.IsWhiteSpace(c)) { i++; continue; }
        if (char.IsDigit(c))
        {
            int wert = 0;
            while (i < text.Length
                   && char.IsDigit(text[i]))
            {
                wert = wert * 10 + (text[i] - '0');
                i++;
            }
            tokens.Add(new Token(Art.Zahl, wert));
            continue;
        }
        Art art = c switch
        {
            '+' => Art.Plus,  '-' => Art.Minus,
            '*' => Art.Mal,   '/' => Art.Durch,
            '(' => Art.KlAuf, ')' => Art.KlZu,
            _ => throw new FormatException(
                $"Unerwartetes Zeichen '{c}'")
        };
        tokens.Add(new Token(art));
        i++;
    }
    tokens.Add(new Token(Art.Ende));
    return tokens;
}

// Felder: List<Token> tokens; int pos;
Token Aktuell => tokens[pos];

void Erwarte(Art art)
{
    if (Aktuell.Art != art)
        throw new FormatException(
          $"{art} erwartet, {Aktuell.Art} gefunden");
    pos++;
}

public int Parse()
{
    int wert = Ausdruck();
    Erwarte(Art.Ende);
    return wert;
}

// Ausdruck = Term { ("+"|"-") Term }
int Ausdruck()
{
    int wert = Term();
    while (Aktuell.Art is Art.Plus or Art.Minus)
    {
        Art op = Aktuell.Art;
        pos++;
        int rechts = Term();
        wert = op == Art.Plus ? wert + rechts
                              : wert - rechts;
    }
    return wert;
}

// Term = Faktor { ("*"|"/") Faktor }
int Term()
{
    int wert = Faktor();
    while (Aktuell.Art is Art.Mal or Art.Durch)
    {
        Art op = Aktuell.Art;
        pos++;
        int rechts = Faktor();
        wert = op == Art.Mal ? wert * rechts
                             : wert / rechts;
    }
    return wert;
}

// Faktor = Zahl | "(" Ausdruck ")"
int Faktor()
{
    if (Aktuell.Art == Art.Zahl)
    {
        int wert = Aktuell.Wert;
        pos++;
        return wert;
    }
    if (Aktuell.Art == Art.KlAuf)
    {
        pos++;
        int wert = Ausdruck();
        Erwarte(Art.KlZu);
        return wert;
    }
    throw new FormatException(
      $"Zahl oder ( erwartet, {Aktuell.Art} gefunden");
}

